// Package schedule parses the five-field cron expressions used by the service
// and computes planned trigger times. All calculations operate on time.Time
// values as absolute instants; callers choose the zone they pass in and the
// service standardises on UTC at its boundaries.
package schedule

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// ErrInvalidExpression is returned whenever a cron expression cannot be used
// to schedule trigger times, including a schedule that never fires.
var ErrInvalidExpression = errors.New("invalid cron expression")

const (
	minuteField = iota
	hourField
	domField
	monthField
	dowField
	fieldCount
)

var fieldBounds = [fieldCount][2]int{
	{0, 59},  // minute
	{0, 23},  // hour
	{1, 31},  // day of month
	{1, 12},  // month
	{0, 7},   // day of week (0 and 7 both mean Sunday)
}

var monthNames = map[string]time.Month{
	"jan": time.January, "feb": time.February, "mar": time.March,
	"apr": time.April, "may": time.May, "jun": time.June,
	"jul": time.July, "aug": time.August, "sep": time.September,
	"oct": time.October, "nov": time.November, "dec": time.December,
}

var weekdayNames = map[string]time.Weekday{
	"sun": time.Sunday, "mon": time.Monday, "tue": time.Tuesday,
	"wed": time.Wednesday, "thu": time.Thursday, "fri": time.Friday,
	"sat": time.Saturday,
}

// Cron is a parsed five-field cron expression.
type Cron struct {
	minute boolSlice
	hour   boolSlice
	dom    boolSlice
	month  boolSlice
	dow    boolSlice

	domRestricted bool
	dowRestricted bool
}

type boolSlice []bool

// Parse validates a standard five-field cron expression:
//
//	┌───────── minute (0-59)
//	│ ┌─────── hour (0-23)
//	│ │ ┌───── day of month (1-31)
//	│ │ │ ┌─── month (1-12 or JAN-DEC)
//	│ │ │ │ ┌─ day of week (0-7 or SUN-SAT; 0 and 7 are Sunday)
//	│ │ │ │ │
//	* * * * *
//
// Each field accepts *, ?, single values, comma lists, a-b ranges and * /n,
// a-b/n style steps. "?" is accepted only in the day fields and behaves like
// "*" for matching purposes.
func Parse(expr string) (*Cron, error) {
	fields := strings.Fields(expr)
	if len(fields) != fieldCount {
		return nil, fmt.Errorf("%w: expected 5 fields, got %d", ErrInvalidExpression, len(fields))
	}

	c := &Cron{}
	parsers := []func(string) (boolSlice, bool, error){
		c.parseMinute, c.parseHour, c.parseDOM, c.parseMonth, c.parseDOW,
	}
	sets := [fieldCount]*boolSlice{&c.minute, &c.hour, &c.dom, &c.month, &c.dow}
	for i, parser := range parsers {
		values, restricted, err := parser(fields[i])
		if err != nil {
			return nil, err
		}
		*sets[i] = values
		if i == domField {
			c.domRestricted = restricted
		}
		if i == dowField {
			c.dowRestricted = restricted
		}
	}
	return c, nil
}

func (c *Cron) parseMinute(raw string) (boolSlice, bool, error) {
	return parseField(raw, fieldBounds[minuteField][0], fieldBounds[minuteField][1], nil)
}

func (c *Cron) parseHour(raw string) (boolSlice, bool, error) {
	return parseField(raw, fieldBounds[hourField][0], fieldBounds[hourField][1], nil)
}

func (c *Cron) parseMonth(raw string) (boolSlice, bool, error) {
	return parseField(raw, fieldBounds[monthField][0], fieldBounds[monthField][1], monthNames)
}

func (c *Cron) parseDOM(raw string) (boolSlice, bool, error) {
	values, restricted, err := parseField(raw, fieldBounds[domField][0], fieldBounds[domField][1], nil)
	if err != nil {
		return nil, false, err
	}
	return values, restricted, nil
}

func (c *Cron) parseDOW(raw string) (boolSlice, bool, error) {
	values, restricted, err := parseField(raw, fieldBounds[dowField][0], fieldBounds[dowField][1], weekdayNames)
	if err != nil {
		return nil, false, err
	}
	if values[7] {
		values[0] = true
	}
	return values, restricted, nil
}

func parseField(raw string, min, max int, names map[string]time.Month) (boolSlice, bool, error) {
	return nil, false, nil
}

// Next returns the earliest matching instant strictly after after.
func (c *Cron) Next(after time.Time) (time.Time, error) {
	return time.Time{}, nil
}
EOF
