	if err := tx.QueryRow(
		`SELECT COUNT(*) FROM run_records WHERE retry_of_seq = ?`, input.RetryOfSeq,
	).Scan(&retryCount); err != nil {
		return RunRecord{}, fmt.Errorf("count retries: %w", err)
